CREATE OR REPLACE FUNCTION public.block_deleted_job_child()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.job_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.jobs j WHERE j.id = NEW.job_id AND j.deleted_at IS NOT NULL) THEN
    IF TG_ARGV[0] = 'skip' THEN RETURN NULL; END IF;
    RAISE EXCEPTION 'This job is deleted; nothing new can be sent or started for it';
  END IF;
  RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.block_deleted_job_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.job_id IS NOT NULL
     AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status::text = ANY (TG_ARGV::text[])
     AND EXISTS (SELECT 1 FROM public.jobs j WHERE j.id = NEW.job_id AND j.deleted_at IS NOT NULL) THEN
    RAISE EXCEPTION 'This job is deleted; queued work cannot be claimed or retried';
  END IF;
  RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.check_job_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.channel = 'installer_sourced' and (new.originating_installer_user_id is null or new.originating_installer_business_id is null) then
    raise exception 'installer-sourced jobs require an originating installer and business';
  end if;
  if new.channel = 'hivic_sourced' and (new.originating_installer_user_id is not null or new.originating_installer_business_id is not null) then
    raise exception 'HI VIC-sourced jobs cannot carry an originating installer';
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.check_worker_token_lifetime()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NEW.token_hash !~ '^[a-f0-9]{64}$' OR NEW.expires_at<=NEW.created_at OR
  NEW.expires_at>NEW.created_at + (CASE WHEN TG_TABLE_NAME='partner_worker_invites' THEN interval '14 days' ELSE interval '30 days' END)
 THEN RAISE EXCEPTION 'Invalid token lifetime'; END IF;
 RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.guard_ap_signature()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.ap_signed_at is not null and (new.ap_signed_at is distinct from old.ap_signed_at or new.ap_signature_name is distinct from old.ap_signature_name
     or new.ap_signed_by is distinct from old.ap_signed_by or new.ap_snapshot_sha256 is distinct from old.ap_snapshot_sha256) then
    raise exception 'signed AP declaration is immutable';
  end if;
  if old.installer_signed_at is not null and new.installer_form_values is distinct from old.installer_form_values then
    raise exception 'signed installer declaration is immutable';
  end if;
  return new;
end $function$
