CREATE OR REPLACE FUNCTION public.guard_owner_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'owner_authorities are permanent records'; end if;
  if new.job_id <> old.job_id or new.owner_id <> old.owner_id or new.property_id <> old.property_id
     or new.version <> old.version or new.wording_version <> old.wording_version
     or new.wording_snapshot <> old.wording_snapshot or new.scope_snapshot <> old.scope_snapshot
     or new.ap_legal_entity <> old.ap_legal_entity or new.owner_full_name <> old.owner_full_name
     or new.property_address <> old.property_address or new.requested_at <> old.requested_at then
    raise exception 'authority snapshot is immutable – issue a new version instead';
  end if;
  if old.accepted_at is not null and (
       new.accepted_at is distinct from old.accepted_at or new.expires_at is distinct from old.expires_at
    or new.confirmed_over_18 is distinct from old.confirmed_over_18
    or new.confirmed_owner_or_authorised is distinct from old.confirmed_owner_or_authorised
    or new.assistance_requirement is distinct from old.assistance_requirement
    or new.signature_name is distinct from old.signature_name or new.ip_address is distinct from old.ip_address
    or new.user_agent is distinct from old.user_agent or new.acceptance_method is distinct from old.acceptance_method
    or new.accepted_by is distinct from old.accepted_by
    or (old.document_sha256 is not null and new.document_sha256 is distinct from old.document_sha256)) then
    raise exception 'accepted authority evidence is immutable';
  end if;
  if old.status in ('declined','revoked','expired') and new.status <> old.status then
    raise exception 'authority in a terminal state cannot change status – issue a new version';
  end if;
  new.updated_at = now();
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_owner_esc_consent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'DELETE' then raise exception 'consent records are permanent'; end if;
  if new.snapshot is distinct from old.snapshot or new.snapshot_sha256 is distinct from old.snapshot_sha256 or new.scheduled_start is distinct from old.scheduled_start then
    raise exception 'consent snapshot is immutable – a new consent version is required';
  end if;
  if old.owner_signed_at is not null and (new.owner_signed_at is distinct from old.owner_signed_at or new.owner_signature_name is distinct from old.owner_signature_name) then
    raise exception 'owner consent signature is immutable';
  end if;
  if old.ap_signed_at is not null and (new.ap_signed_at is distinct from old.ap_signed_at or new.ap_rep_name is distinct from old.ap_rep_name) then
    raise exception 'AP consent confirmation is immutable';
  end if;
  if old.status in ('stale','cancelled') and new.status <> old.status then raise exception 'stale/cancelled consent cannot be revived'; end if;
  new.updated_at = now();
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.guard_owner_ready_check_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  PERFORM 1 FROM public.workflow_settings WHERE id=1 FOR SHARE;
  PERFORM 1 FROM public.jobs WHERE id=NEW.job_id FOR SHARE;
  IF NOT public.owner_ready_check_booking_allowed(NEW.job_id) THEN
    RAISE EXCEPTION 'Ready Check booking is not open. We''ll be in touch when the office offers your booking.';
  END IF;
  RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.guard_partner_rate_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'rate_offer:immutable'; END IF;
  IF NEW.items IS DISTINCT FROM OLD.items OR NEW.round <> OLD.round OR NEW.application_id <> OLD.application_id
     OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at
     OR NEW.note IS DISTINCT FROM OLD.note OR NEW.gst_registered <> OLD.gst_registered THEN RAISE EXCEPTION 'rate_offer:immutable'; END IF;
  IF OLD.status <> 'sent' THEN RAISE EXCEPTION 'rate_offer:already_answered'; END IF;
  IF NEW.status <> 'sent' AND NEW.token_hash <> OLD.token_hash THEN RAISE EXCEPTION 'rate_offer:immutable'; END IF;
  IF NEW.status = 'accepted' AND (OLD.expires_at IS NULL OR OLD.expires_at < now()) THEN RAISE EXCEPTION 'rate_offer:expired'; END IF;
  RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.guard_qa_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
