  IF OLD.state IN ('accepted','deleted') THEN RAISE EXCEPTION 'Upload record is final'; END IF;
  IF NEW.path IS DISTINCT FROM OLD.path OR NEW.application_id IS DISTINCT FROM OLD.application_id THEN RAISE EXCEPTION 'Upload identity is immutable'; END IF;
  RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.guard_ready_check_booking_control()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF (NEW.ready_check_booking_offered_at IS DISTINCT FROM OLD.ready_check_booking_offered_at
    OR NEW.ready_check_booking_offered_by IS DISTINCT FROM OLD.ready_check_booking_offered_by)
    AND NOT public.is_admin() AND current_setting('role',true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Only office can offer Ready Check booking';
  END IF;
  RETURN NEW;
END $function$
CREATE OR REPLACE FUNCTION public.guard_ready_check_payment_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.id <> OLD.id OR NEW.acceptance_id <> OLD.acceptance_id OR NEW.job_id <> OLD.job_id
     OR NEW.purpose <> OLD.purpose OR NEW.amount_inc_gst <> OLD.amount_inc_gst
     OR NEW.mode <> OLD.mode OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'ready check payment identity and amount are immutable';
  END IF;
  IF OLD.status = 'paid' AND (NEW.status <> OLD.status OR NEW.paid_at IS DISTINCT FROM OLD.paid_at) THEN
    RAISE EXCEPTION 'paid ready check payment is immutable';
  END IF;
  IF OLD.credit_applied_to_quote_id IS NOT NULL AND NEW.credit_applied_to_quote_id IS DISTINCT FROM OLD.credit_applied_to_quote_id THEN
    RAISE EXCEPTION 'ready check credit can be applied only once';
  END IF;
  IF NEW.attempt_count < OLD.attempt_count THEN RAISE EXCEPTION 'attempt count cannot decrease'; END IF;
  NEW.updated_at = now();
  RETURN NEW;
END $function$
